 function pipelinePanel(count){const allClips={length:count};return `<section class="settings-section"><h2>分人语音条</h2><p class="muted">按说话人分组，再按停顿拆成最长18秒的语音条，自动识别原语言文字，再校正时间段和说话人。文件和录音保存在当前会话中，每份音频单独成组，保留原音频和已修改的文字。</p><div class="recording-toolbar"><select id="pipeline-language" aria-label="转写语言"><option value="auto">自动识别语言</option><option value="en">英语</option><option value="zh">中文</option><option value="ja">日语</option><option value="ko">韩语</option><option value="yue">粤语</option></select><select id="pipeline-count" aria-label="说话人数"><option value="0">自动估计人数</option>${Array.from({length:8},(_,i)=>`<option value="${i+1}">${i+1} 人</option>`).join('')}</select><button class="button" id="pipeline-session" ${!allClips.length?'disabled':''}>解析待处理录音</button><button class="button" id="pipeline-import">${sessionId?'添加音频到当前会话':'导入音频并新建会话'}</button><button class="button" id="pipeline-cancel" hidden>取消处理</button></div><p class="muted">本地处理，单次最多4小时。A/B 是本次任务的声音分组，不代表已确认身份；短插话、重叠发言和文字均需核对。</p></section>`;}
 function bindPipeline(){root.querySelector("#pipeline-session").onclick=()=>startPipeline("session");root.querySelector("#pipeline-import").onclick=()=>startPipeline("import");root.querySelector("#pipeline-cancel").onclick=()=>api.speakerPipeline({action:"cancel"}).catch(e=>status(e.message));resumePipeline();}
