   if(job.state==='completed'){sessionId=job.recording_id;speakerFilter='';await reload();status(`已生成 ${job.clip_count} 条分人语音，${job.review_count} 条建议复核声音归属。原文已自动识别，请核对文字、时间和说话人。`);}
