  const viewport=group.querySelector('.conversation-source-clips'),slider=group.querySelector('[data-scroll-position]'),label=group.querySelector('[data-scroll-label]'),range=group.querySelector('[data-scroll-range]'),rows=[...viewport.querySelectorAll('.chat-message')],key=sessionId+':'+group.dataset.sourceKey;
