  handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();handle.focus({preventScroll:true});drag={id:e.pointerId,y:e.clientY,height:listHeight,scale:panel.getBoundingClientRect().height/panel.offsetHeight||1};handle.setPointerCapture(e.pointerId);handle.classList.add('is-resizing');};
